```typescript
export class OrderService {
  async getCustomerSummary(customerId: string) {
    const orders = await db.orders.findMany({ where: { customerId } });
    for (const order of orders) {
      order.items = await db.orderItems.findMany({ where: { orderId: order.id } });
      order.payments = await db.payments.findMany({ where: { orderId: order.id } });
    }
    return orders;
  }

  async checkout(cartId: string) {
    const cart = await db.carts.findUnique({ where: { id: cartId } });
    if (cart.status === 'checked_out') return { error: 'already checked out' };
    await paymentGateway.charge(cart.total);
    await db.carts.update({ where: { id: cartId }, data: { status: 'checked_out' } });
    return { success: true };
  }
}
